// machines/plaits: SWARM's per-grain sample loop (engines/swarm.c), hand-written SISD kernel.
// Generated by lib/gen_swarm_kernel.py; do not edit by hand.
//
// swarm_grain_kernel(float *g, float *out, float *aux, int size): g[0..11] = fm_v, fm_i, gn_v, gn_i, ep_v, ep_i, am_v,
//   am_i, saw_phase, saw_next, sx, sy (the grain's interpolators and oscillator state as swarm_render holds them in
//   its locals); adds the grain's saw to out and its sine to aux and writes the values back to g (g[0, 2, 4, 6, 8..11]).
//   Bit-identical to selcc's code of the C loop (-DPL_SWARM_C) (tests/plaits/test_swarm_kernel.py).
//
// State on return: R0-R8, R12, I4 and the flags change; every other register is as on entry (R9-R11, R13-R15 saved
// above I7; I0, I1, M6, L0, L1, L4 pushed through R0, M6 = 1 and L0 = L1 = L4 = 0 set here). No SIMD.
// ABI: as the other kernels (lib/wavetable_sm.s). Assembled under .COMPRESS.

.SECTION/PM seg_pmco;
.GLOBAL swarm_grain_kernel.;
.COMPRESS;

swarm_grain_kernel.:
    R0 = I0;
    DM(I7, M7) = R0;
    R0 = I1;
    DM(I7, M7) = R0;
    R0 = M6;
    DM(I7, M7) = R0;
    R0 = L0;
    DM(I7, M7) = R0;
    R0 = L1;
    DM(I7, M7) = R0;
    R0 = L4;
    DM(I7, M7) = R0;
    M6 = 1;
    L0 = 0;
    L1 = 0;
    L4 = 0;
    I7=MODIFY (I7,-8)(NW);
    DM(1, I7) = R9;
    DM(2, I7) = R10;
    DM(3, I7) = R11;
    DM(4, I7) = R13;
    DM(5, I7) = R14;
    DM(6, I7) = R15;
    I4 = R4;                                            // g
    I0 = R8;                                            // out
    I1 = R12;                                           // aux
    R0 = DM(1, I6);                                     // size
    DM(8, I7) = R0;
    R15 = DM(0, I4);                                    // fm_v
    R14 = DM(1, I4);                                    // fm_i
    R13 = DM(2, I4);                                    // gn_v
    R12 = DM(3, I4);                                    // gn_i
    R11 = DM(4, I4);                                    // ep_v
    R10 = DM(5, I4);                                    // ep_i
    R9 = DM(6, I4);                                     // am_v
    R8 = DM(7, I4);                                     // am_i
    R7 = DM(8, I4);                                     // saw_phase
    R6 = DM(9, I4);                                     // saw_next
    R5 = DM(10, I4);                                    // sx
    R4 = DM(11, I4);                                    // sy
    DM(7, I7) = R8;                                     // am_i (R8 is a temporary in the loop)
    R1 = 0;
    COMP(R0, R1);
    IF LE JUMP _swg_done;
_swg_loop:
    R1 = PASS R6;                                       // this_sample = saw_next
    R6 = 0;                                             // saw_next = 0.0f
    F15 = F15 + F14;                                    // fq = fm_v += fm_i
    F7 = F7 + F15;                                      // saw_phase += fq
    R0 = 0x3F800000;
    COMP(F7, F0);                                       // saw_phase >= 1.0f
    IF LT JUMP _swg_nr;
    F7 = F7 - F0;                                       // saw_phase -= 1.0f
    R3 = 0x40000000;
    F0 = RECIPS F15;                                    // t = saw_phase / fq (selcc division)
    F8 = F15 * F0;
    F8 = F3 - F8;
    F0 = F0 * F8;
    F8 = F15 * F0;
    F8 = F3 - F8;
    F0 = F0 * F8;
    F3 = F7 * F0;
    F8 = F15 * F3;
    F8 = F7 - F8;
    F8 = F8 * F0;
    F2 = F3 + F8;
    R0 = 0x3F000000;
    F0 = F0 * F2;                                       // this_sample -= ThisBlepSample(t)
    F0 = F0 * F2;
    F1 = F1 - F0;
    R0 = 0x3F800000;
    F3 = F0 - F2;                                       // saw_next -= NextBlepSample(t)
    R0 = 0xBF000000;
    F0 = F0 * F3;
    F0 = F0 * F3;
    F6 = F6 - F0;
_swg_nr:
    F6 = F6 + F7;                                       // saw_next += saw_phase
    F13 = F13 + F12;                                    // gn_v += gn_i
    R0 = 0x40000000;
    F0 = F0 * F1;                                       // out[n] += (2.0f * this_sample - 1.0f) * gn_v
    R2 = 0x3F800000;
    F0 = F0 - F2;
    F0 = F0 * F13;
    R2 = DM(I0, M5);
    F2 = F2 + F0;
    DM(I0, M6) = R2;
    F11 = F11 + F10;                                    // e = ep_v += ep_i
    F0 = F11 * F4;                                      // sx += e * sy
    F5 = F5 + F0;
    F0 = F11 * F5;                                      // sy -= e * sx
    F4 = F4 - F0;
    R0 = DM(7, I7);
    F9 = F9 + F0;                                       // am_v += am_i
    F0 = F9 * F5;                                       // aux[n] += am_v * sx
    R2 = DM(I1, M5);
    F2 = F2 + F0;
    DM(I1, M6) = R2;
    R0 = DM(8, I7);
    R1 = 1;
    .NOCOMPRESS;
    R0 = R0 - R1;
    .COMPRESS;
    DM(8, I7) = R0;
    IF NE JUMP _swg_loop;
_swg_done:
    DM(0, I4) = R15;                                    // fm_v
    DM(2, I4) = R13;                                    // gn_v
    DM(4, I4) = R11;                                    // ep_v
    DM(6, I4) = R9;                                     // am_v
    DM(8, I4) = R7;                                     // saw_phase
    DM(9, I4) = R6;                                     // saw_next
    DM(10, I4) = R5;                                    // sx
    DM(11, I4) = R4;                                    // sy
    R9 = DM(1, I7);
    R10 = DM(2, I7);
    R11 = DM(3, I7);
    R13 = DM(4, I7);
    R14 = DM(5, I7);
    R15 = DM(6, I7);
    I7=MODIFY (I7,8)(NW);
    L4 = DM(1, I7);
    L1 = DM(2, I7);
    L0 = DM(3, I7);
    M6 = DM(4, I7);
    I1 = DM(5, I7);
    I0 = DM(6, I7);
    I12 = DM(M7, I6);
    JUMP (M14, I12) (DB);
    RFRAME;
    NOP;
